function validate([nums1, nums2]) {
  if (!Array.isArray(nums1) || !Array.isArray(nums2)) return 'nums1 and nums2 must be arrays.';
  if (nums1.length < 1 || nums1.length > 100000 || nums2.length < 1 || nums2.length > 100000) return 'Each array needs 1 to 10^5 values.';
  for (const arr of [nums1, nums2]) {
    for (let k = 0; k < arr.length; k++) {
      if (!Number.isInteger(arr[k]) || arr[k] < 1 || arr[k] > 10000000) return 'Each value is an integer from 1 to 10^7.';
      if (k > 0 && arr[k] <= arr[k - 1]) return 'Both arrays must be strictly increasing.';
    }
  }
  return null;
}

