function maxSum(nums1, nums2) {
  const arrays = [nums1, nums2];
  const where = [new Map(nums2.map((v, k) => [v, k])), new Map(nums1.map((v, k) => [v, k]))];
  const memo = new Map();
  // Best score collectable from reading arrays[side][idx] onwards.
  const walk = (side, idx) => {
    const arr = arrays[side];
    if (idx >= arr.length) return 0;
    const key = side + ':' + idx;
    if (memo.has(key)) return memo.get(key);
    let rest = walk(side, idx + 1);
    const other = where[side].get(arr[idx]);
    if (other !== undefined) rest = Math.max(rest, walk(1 - side, other + 1));
    const total = arr[idx] + rest;
    memo.set(key, total);
    return total;
  };
  return Math.max(walk(0, 0), walk(1, 0)) % 1000000007;
}

