function generate(rand, size) {
  const large = size === 'large';
  const n1 = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 7);
  const n2 = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 7);
  const step = large ? 3000 : 3;
  const shareChance = 0.1 + rand() * 0.5;
  const a = [], b = [];
  let v = 0;
  while (a.length < n1 || b.length < n2) {
    v += 1 + Math.floor(rand() * step);
    if (v > 10000000) break;
    if (a.length < n1 && b.length < n2 && rand() < shareChance) { a.push(v); b.push(v); }
    else if (b.length >= n2 || (a.length < n1 && rand() < 0.5)) a.push(v);
    else b.push(v);
  }
  if (!a.length) a.push(v + 1);
  if (!b.length) b.push(v + 2);
  return [a, b];
}
